import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const srcRoot = path.join(root, 'source', 'sravni-plitku');
const outDir = path.join(root, 'uiux-kit');
const outFile = path.join(outDir, 'sravni-plitku-uiux-kit.json');
const textExt = new Set(['.css','.html','.php','.js','.json','.md','.sql']);

function walk(dir, acc = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name === 'vendor') continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) walk(full, acc);
    else if (textExt.has(path.extname(entry.name).toLowerCase())) acc.push(full);
  }
  return acc;
}

const files = walk(srcRoot).sort();
const rel = f => path.relative(root, f).replaceAll('\\', '/');
const texts = files.map(file => ({ file, rel: rel(file), text: fs.readFileSync(file, 'utf8') }));
const cssTexts = texts.filter(x => x.rel.endsWith('.css'));
const sourceClasses = [...new Set(cssTexts.flatMap(x => [...x.text.matchAll(/\.([A-Za-z_-][A-Za-z0-9_-]*)/g)].map(m => m[1])))] .sort();
const mediaQueries = [...new Set(cssTexts.flatMap(x => [...x.text.matchAll(/@media\s*\(([^)]+)\)/g)].map(m => m[1].trim())))] .sort();
const cssVariables = [...new Set(cssTexts.flatMap(x => [...x.text.matchAll(/(--[A-Za-z0-9_-]+)\s*:/g)].map(m => m[1])))] .sort();
const inlineStyleCount = texts.filter(x => /\.(?:html|php|js)$/.test(x.rel)).reduce((n,x) => n + [...x.text.matchAll(/style\s*=\s*["'][^"']*["']/g)].length, 0);

const clamp = (n, min, max) => Math.max(min, Math.min(max, n));
function normalizeHex(input) {
  let h = input.replace('#','').trim();
  if (h.length === 3) h = h.split('').map(c => c+c).join('');
  return `#${h.slice(0,6).toUpperCase()}`;
}
function rgbFromHex(hex) {
  const h = normalizeHex(hex).slice(1);
  return [parseInt(h.slice(0,2),16), parseInt(h.slice(2,4),16), parseInt(h.slice(4,6),16)];
}
function hslFromRgb([r,g,b]) {
  r/=255; g/=255; b/=255;
  const max=Math.max(r,g,b), min=Math.min(r,g,b), d=max-min;
  let h=0;
  if (d) h = max===r ? ((g-b)/d)%6 : max===g ? (b-r)/d+2 : (r-g)/d+4;
  h = Math.round((h*60+360)%360);
  const l=(max+min)/2;
  const s=d===0?0:d/(1-Math.abs(2*l-1));
  return [h, +(s*100).toFixed(2), +(l*100).toFixed(2)];
}
function oklchFromRgb([r,g,b]) {
  const lin = v => { v/=255; return v<=.04045?v/12.92:((v+.055)/1.055)**2.4; };
  r=lin(r); g=lin(g); b=lin(b);
  const l=.4122214708*r+.5363325363*g+.0514459929*b;
  const m=.2119034982*r+.6806995451*g+.1073969566*b;
  const s=.0883024619*r+.2817188376*g+.6299787005*b;
  const l3=Math.cbrt(l), m3=Math.cbrt(m), s3=Math.cbrt(s);
  const L=.2104542553*l3+.793617785*m3-.0040720468*s3;
  const A=1.9779984951*l3-2.428592205*m3+.4505937099*s3;
  const B=.0259040371*l3+.7827717662*m3-.808675766*s3;
  const C=Math.sqrt(A*A+B*B), H=(Math.atan2(B,A)*180/Math.PI+360)%360;
  return [+(L*100).toFixed(2), +C.toFixed(4), +H.toFixed(2)];
}
function luminance([r,g,b]) {
  const f=v=>{v/=255;return v<=.03928?v/12.92:((v+.055)/1.055)**2.4;};
  return .2126*f(r)+.7152*f(g)+.0722*f(b);
}
function ratio(a,b) { const x=Math.max(a,b), y=Math.min(a,b); return +((x+.05)/(y+.05)).toFixed(2); }
function wcag(r) { return { normal_text: r>=7?'AAA':r>=4.5?'AA':'fail', large_text: r>=4.5?'AAA':r>=3?'AA':'fail' }; }
function color(value, comment, extra={}) {
  const hex=normalizeHex(value), rgb=rgbFromHex(hex), hsl=hslFromRgb(rgb), oklch=oklchFromRgb(rgb);
  const cw=ratio(luminance(rgb),1), cb=ratio(luminance(rgb),0);
  return { value:hex, rgb:`rgb(${rgb.join(', ')})`, hsl:`hsl(${hsl[0]} ${hsl[1]}% ${hsl[2]}%)`, oklch:`oklch(${oklch[0]}% ${oklch[1]} ${oklch[2]})`, contrast:{ white:{ratio:cw,...wcag(cw)}, black:{ratio:cb,...wcag(cb)} }, comment, ...extra };
}
